<section id="roles" data-access-panel><h2 tabindex="-1">Roles</h2>
<?php if($can('roles.manage')):?><details class="card"><summary>Create Role</summary><form method="post"><label for="role-code">Role code</label><input id="role-code" name="code" pattern="[a-z][a-z0-9_.\-]{2,59}" maxlength="60" required><label for="role-description">Description</label><input id="role-description" name="description" maxlength="255" required><?php access_management_fields('create_role')?><p class="access-actions"><button>Create Role</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<?php foreach($roles as $role):?><details class="card"><summary><?=access_h($role['name'])?></summary><p><?=access_h($role['description'])?></p><?php if($role['name']==='admin'):?><p>The administrator role retains all built-in privileges.</p><?php elseif($can('roles.manage')&&$accessRoleEditable[$role['id']]):?><form method="post" class="checks" data-permission-preview><h2>Assigned Privileges</h2><?php foreach($privileges as $privilege):?><label><input type="checkbox" name="ids[]" value="<?=(int)$privilege['id']?>" data-permission-labels="<?=access_h(json_encode((object)[(int)$privilege['id']=>$accessPreviewLabels[(int)$privilege['id']]],JSON_THROW_ON_ERROR))?>" <?=in_array((int)$privilege['id'],$rolePrivileges[$role['id']] ?? [],true)?'checked':''?>><?=access_h($privilege['code'])?> · <?=access_h($privilege['description'])?></label><?php endforeach?><p data-permission-changes role="status" hidden></p><?php access_management_fields('assign_privileges',(int)$role['id'])?><p class="access-actions"><button>Save Privileges</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form><?php elseif($can('roles.manage')):?><p class="muted">Read Only: This Role Is Above Your Authority.</p><?php endif?></details><?php endforeach?></section>
